const ok  = (value)  => ({ ok: true,  value });
const err = (reason) => ({ ok: false, reason });

const match = (result, handlers) =>
    result.ok ? handlers.onOk(result.value) : handlers.onErr(result.reason);

const parsed = Number.parseInt(input, 10);
const result = Number.isNaN(parsed) ? err(`not a number: ${input}`) : ok(parsed);

console.log(match(result, {
    onOk:  (value)  => value * 2,
    onErr: (reason) => `failed: ${reason}`,
}));
